(()=>{'use strict';const all={"pt": {"eyebrow": "ENTENDER, DISCERNIR E MUDAR", "title": "Entender o pecado. Cultivar uma vida de amor.", "intro": "O que a Bíblia chama de pecado? Como reconhecer atitudes que ferem nossa relação com Deus e com o próximo? Aqui, o estudo se liga a exemplos e a caminhos de arrependimento, cuidado e reparação.", "summaryNote": "As explicações são sínteses e aplicações da plataforma, não citações literais. Abra as referências para ler a passagem em seu contexto. Não é uma lista completa de todos os pecados.", "definitionTitle": "O que é pecado?", "definition": "Na perspectiva bíblica, pecado envolve transgredir a vontade de Deus e praticar a injustiça. Também pode envolver omitir o bem que sabemos que devemos fazer. O exame inclui ações, palavras, desejos cultivados e omissões, em vez de apenas a aparência religiosa.", "definitionRefs": [{"label": "1 João 3:4", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}, {"label": "1 João 5:17", "url": "https://www.bibliaonline.com.br/acf/1jo/5"}, {"label": "Tiago 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "Marcos 7:20–23", "url": "https://www.bibliaonline.com.br/acf/mc/7"}], "idolatryTitle": "Idolatria: o que ocupa o lugar de Deus?", "idolatry": "A fé bíblica rejeita dar a outro o lugar que pertence a Deus. O problema também aparece quando dinheiro, poder ou interesses se tornam absolutos e justificam prejudicar alguém. Colossenses associa a avareza à idolatria; Jesus contrasta servir a Deus e ao dinheiro.", "idolatryExample": "Exemplo: defender a própria fé não autoriza ameaçar, humilhar ou agredir quem crê de outra forma. A pessoa pode discordar com firmeza e ainda tratar o outro com dignidade. O ódio e a violência precisam ser examinados como atitudes, sem condenar um grupo inteiro.", "idolatryRefs": [{"label": "Êxodo 20:3–6", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Mateus 6:24", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Colossenses 3:5", "url": "https://www.bibliaonline.com.br/acf/cl/3"}, {"label": "Mateus 5:43–48", "url": "https://www.bibliaonline.com.br/acf/mt/5"}, {"label": "1 João 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}], "images": "O uso de imagens recebe interpretações distintas entre tradições cristãs. O Catecismo católico distingue veneração de imagens e adoração devida somente a Deus (2132). Ao comparar práticas, identifique a tradição e o que ela ensina, em vez de presumir a intenção de cada pessoa.", "imagesAction": "Consultar a explicação católica sobre imagens", "gravityTitle": "Pecado mortal, venial e capital: qual a diferença?", "gravity": "Na doutrina católica, pecado mortal exige, juntos: matéria grave, pleno conhecimento e consentimento deliberado. O venial envolve matéria leve ou ausência de pleno conhecimento/consentimento em matéria grave. Não basta uma lista de atos para julgar a responsabilidade de alguém.", "gravityNote": "Outras comunidades cristãs não usam necessariamente essa classificação da mesma forma. A distinção é apresentada aqui como doutrina católica, com a fonte para consulta.", "gravityAction": "Ler Catecismo 1854–1864", "graveTitle": "Exemplos de condutas graves para estudar", "graveIntro": "As referências ajudam a reconhecer o mal e a buscar mudança. A gravidade de uma conduta e a responsabilidade pessoal não devem ser confundidas com um julgamento automático sobre a situação espiritual de alguém.", "examples": [["Violência e homicídio", "Atentar contra a vida, ameaçar e humilhar ferem o próximo. Jesus também confronta a ira que se expressa em ofensa.", "Interrompa a agressão e procure segurança e ajuda. Reconciliação não exige permanecer em uma situação violenta.", [{"label": "Êxodo 20:13", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Mateus 5:21–24", "url": "https://www.bibliaonline.com.br/acf/mt/5"}]], ["Roubo, mentira e fraude", "Tomar o que é do outro, enganar para obter vantagem e dar falso testemunho destroem confiança e causam prejuízo.", "Reconheça o erro, corrija a informação e procure reparar o dano de modo responsável.", [{"label": "Êxodo 20:15–16", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Efésios 4:25–28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Infidelidade e uso de outras pessoas", "Adultério, exploração e relações que desrespeitam a dignidade do outro contradizem fidelidade e cuidado.", "Estabeleça limites, abandone a conduta prejudicial e busque orientação responsável.", [{"label": "Êxodo 20:14", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "1 Tessalonicenses 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Ganância e exploração", "Colocar o ganho acima da justiça pode levar a explorar, reter o que é devido e tratar pessoas como meios para enriquecer.", "Pratique acordos justos e honestidade. Partilhe conforme suas possibilidades e responsabilidades.", [{"label": "Lucas 12:13–21", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "Tiago 5:1–6", "url": "https://www.bibliaonline.com.br/acf/tg/5"}]], ["Ódio e palavras que ferem", "Calúnia, desprezo e palavras usadas para destruir não combinam com o amor ao próximo.", "Faça uma pausa, evite enviar a ofensa e procure expressar o conflito com verdade e respeito.", [{"label": "Efésios 4:29–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "1 João 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}]], ["Omissão diante da necessidade", "Saber que podemos fazer o bem e deliberadamente ignorá-lo também pede exame. O cuidado precisa considerar o que realmente está ao nosso alcance.", "Escolha uma ajuda concreta possível, sem expor ou constranger quem a recebe.", [{"label": "Tiago 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "1 João 3:17–18", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}]]], "causesTitle": "O que pode nos conduzir ao erro?", "causesIntro": "Tiago descreve um percurso entre desejo cultivado e pecado. Na prática, vale observar escolhas, hábitos e justificativas. O ambiente influencia oportunidades, mas um lugar calmo não garante ausência de ira e uma aparência religiosa não garante integridade.", "causes": ["Desejar uma vantagem e justificar o prejuízo que ela causa.", "Repetir uma conduta até deixar de examinar suas consequências.", "Ceder à pressão de um grupo ou à necessidade de parecer superior.", "Guardar ressentimento e escolher alimentar a vingança.", "Ignorar uma correção e procurar somente quem confirma nossas escolhas.", "Confundir uma tentação ou um pensamento involuntário com uma decisão deliberada: sentir ou pensar algo não é automaticamente escolher praticá-lo."], "causesRefs": [{"label": "Tiago 1:13–15", "url": "https://www.bibliaonline.com.br/acf/tg/1"}, {"label": "Romanos 12:2", "url": "https://www.bibliaonline.com.br/acf/rm/12"}, {"label": "Provérbios 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}], "capitalTitle": "Os sete pecados capitais na vida cotidiana", "capitalNote": "Os capitais são vícios que favorecem outros pecados; não equivalem automaticamente a pecados mortais.", "capitalIntro": "A proposta é ligar o ensinamento a atitudes concretas: reconhecer o que prejudica, cultivar uma virtude e preparar condições para agir melhor. Os exemplos abaixo são aplicações, não diagnósticos sobre pessoas.", "capital": [["Soberba", "Humildade", "Buscar superioridade e desprezar o outro pode impedir a escuta e a correção.", "Escute uma opinião com atenção, reconheça um erro e agradeça uma ajuda.", [{"label": "Filipenses 2:3–8", "url": "https://www.bibliaonline.com.br/acf/fp/2"}]], ["Avareza e ganância", "Generosidade e justiça", "Colocar o acúmulo acima de tudo pode fechar espaço à partilha e à honestidade.", "Cumpra o que é devido, recuse vantagens injustas e separe uma ajuda compatível com seus recursos.", [{"label": "Lucas 12:15", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "Efésios 4:28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Inveja", "Gratidão e benevolência", "A comparação alimentada pode virar ressentimento e desejo de diminuir o bem do outro.", "Reconheça uma qualidade de alguém sem transformar a conversa em competição.", [{"label": "Tiago 3:13–18", "url": "https://www.bibliaonline.com.br/acf/tg/3"}]], ["Ira destrutiva", "Mansidão e domínio próprio", "A raiva pode virar insulto, ameaça ou agressão quando escolhemos alimentá-la e ferir.", "Reduza estímulos de confronto, faça uma pausa e retome a conversa com segurança e respeito.", [{"label": "Efésios 4:26–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "Provérbios 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}]], ["Luxúria", "Respeito e fidelidade", "Reduzir alguém a objeto e trair compromissos fere relações e dignidade.", "Prepare limites para condutas prejudiciais e escolha relações de respeito, sem exploração.", [{"label": "1 Tessalonicenses 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Gula", "Temperança e cuidado", "O estudo da temperança convida a examinar excessos, desperdício e falta de partilha. O corpo de alguém não revela sua vida moral.", "Cuide da alimentação conforme suas necessidades e acesso, evite desperdício e partilhe quando possível.", [{"label": "1 Coríntios 10:23–31", "url": "https://www.bibliaonline.com.br/acf/1co/10"}, {"label": "Isaías 58:7", "url": "https://www.bibliaonline.com.br/acf/is/58"}]], ["Preguiça ou negligência espiritual", "Diligência possível", "É preciso distinguir abandonar deliberadamente uma responsabilidade de precisar de descanso ou enfrentar limitações reais.", "Escolha uma tarefa possível e peça apoio. Cansaço, TDAH, depressão e doença não são automaticamente negligência moral.", [{"label": "Romanos 12:9–13", "url": "https://www.bibliaonline.com.br/acf/rm/12"}]]], "fastingTitle": "Jejum, gula e alimentação: como relacionar com cuidado?", "fasting": "Em Mateus 6:16–18, Jesus ensina a jejuar sem exibição religiosa. Isaías 58 relaciona o jejum à justiça, à libertação da opressão e à partilha do pão. A plataforma propõe refletir sobre humildade, domínio próprio e generosidade a partir dessas passagens.", "fastingHealth": "Jejum religioso não é garantia de emagrecimento, prevenção de diabetes ou ausência de doença. Peso e diagnóstico não medem santidade nem permitem concluir que alguém pratica gula. Quem tem diabetes deve consultar a equipe de saúde antes de jejuar; não altere alimentação ou medicamentos por conta própria para cumprir um desafio do site.", "fastingPractice": "Um passo possível: examine o desperdício, cuide de uma refeição conforme sua realidade e compartilhe algo que esteja ao seu alcance. Se desejar jejuar, converse sobre a prática com sua comunidade e respeite a orientação de saúde. Não há duração, competição ou meta de peso proposta aqui.", "fastingRefs": [{"label": "Mateus 6:16–18", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Isaías 58:6–10", "url": "https://www.bibliaonline.com.br/acf/is/58"}], "fastingHealthAction": "Diabetes e jejum · orientação da IDF", "changeTitle": "Reconhecer, arrepender-se e reparar", "changeIntro": "O objetivo não é permanecer preso à acusação, mas buscar verdade, perdão e mudança. A história de Zaqueu liga o encontro com Jesus à reparação; Tiago chama a colocar a Palavra em prática.", "changeSteps": ["Reconheça uma atitude concreta, sem reduzir toda a sua identidade a ela.", "Volte-se para Deus em oração e busque orientação em sua comunidade de fé.", "Interrompa o dano e respeite a segurança de quem foi atingido.", "Faça a reparação possível com responsabilidade; pedir perdão não obriga a outra pessoa a retomar uma relação.", "Prepare um hábito e um ambiente que apoiem a mudança. Se precisar, procure ajuda qualificada."], "changeRefs": [{"label": "Lucas 19:1–10", "url": "https://www.bibliaonline.com.br/acf/lc/19"}, {"label": "1 João 1:8–9", "url": "https://www.bibliaonline.com.br/acf/1jo/1"}, {"label": "Tiago 1:22", "url": "https://www.bibliaonline.com.br/acf/tg/1"}], "careNote": "Este estudo não deve ser usado para humilhar, diagnosticar ou perseguir pessoas. Se o tema estiver provocando angústia intensa, você pode fazer uma pausa e buscar apoio humano.", "practiceLabel": "Um passo possível", "virtueLabel": "Cultivar", "read": "Ler a passagem · ACF em português ↗", "sourceLabel": "Fontes doutrinais e limites", "sourceText": "Síntese cristã introdutória. A classificação mortal/venial e a explicação católica sobre imagens são identificadas pela tradição. Questões pastorais específicas pedem acompanhamento, sem veredictos automáticos sobre pessoas.", "seekingLink": "Entender o pecado →", "careLink": "Jejum e alimentação: entender com cuidado →", "helpLink": "Acolhimento e apoio →", "studyLink": "Continuar no espaço Buscando →", "everydayTitle": "Da igreja à vida: reconhecer o erro no cotidiano", "everydayIntro": "Conhecer um nome não basta: o estudo ganha sentido quando percebemos a atitude, o dano e uma saída possível. As situações abaixo são ilustrativas, não relatos reais nem uma ferramenta para julgar a consciência de outras pessoas.", "sceneLabel": "A situação", "discernLabel": "O que examinar", "actionLabel": "Um caminho de mudança", "reasonTitle": "Um raciocínio para levar à vida", "reasonText": "Uma prática religiosa pode nos ensinar, mas a presença no culto, sozinha, não garante coerência fora dele. Podemos perguntar: o que estou buscando? Que meios estou usando? Quem é atingido? Estou respeitando a verdade e a dignidade? Que atitude de justiça e amor posso escolher agora? Não é necessário vigiar cada pensamento sem descanso; o propósito é reconhecer escolhas concretas e aprender a agir.", "planLink": "Temas propostos para palestras, artigos e livros →", "everyday": [["Quando o olhar vira cobiça", "Você percebe alguém atraente ou vê um bem que gostaria de ter. Perceber isso não é o mesmo que decidir explorar uma pessoa, trair um compromisso ou tomar o que pertence ao outro.", "O ponto de exame é o que você escolhe alimentar: transformar alguém em objeto, justificar uma traição ou cultivar um plano de engano para obter o que deseja. A tentação não torna roubo ou violência inevitáveis.", "Reconheça o desejo sem tratá-lo como uma ordem. Respeite a pessoa e seus compromissos; interrompa a conduta que causa dano. Se a busca se tornou um hábito prejudicial, peça apoio para mudar.", "Mateus 5:27–30 · Tiago 1:13–15"], ["O prato, o desperdício e a partilha", "Há comida disponível, mas também há alguém precisando. O exame não é medir o corpo de quem come: é perguntar como usamos os recursos e se podemos repartir com responsabilidade.", "Desperdiçar por ostentação ou recusar deliberadamente uma ajuda possível pode revelar indiferença. A necessidade de alimento varia; comer o necessário ou tratar uma doença não é uma falha moral.", "Organize uma refeição dentro das suas condições, cuide do que pode ser aproveitado e ofereça uma ajuda possível, sem vigiar o prato ou humilhar o corpo de ninguém.", "Isaías 58:7 · 1 João 3:17–18"], ["Ira numa conversa ou nas redes", "Uma discordância desperta raiva. O sentimento pode ser reconhecido sem que você envie uma ameaça, exponha alguém ou transforme o conflito em agressão.", "Observe o momento em que a intenção deixa de esclarecer um problema e passa a ferir. Um ambiente menos provocativo pode ajudar, mas também é preciso escolher limites e formas de responder.", "Pare antes de publicar, verifique o que entendeu e retome o assunto com respeito, quando houver segurança. Se houve dano, reconheça-o e procure reparação.", "Efésios 4:26–32 · Provérbios 15:1"], ["Ganhar mais e esquecer quem está ao lado", "Desejar melhorar de vida ou guardar recursos para necessidades reais não equivale automaticamente à ganância. O problema aparece quando o ganho vale mais que a justiça e a dignidade.", "Examine fraude, retenção do que é devido, exploração e a ideia de que qualquer meio é aceitável para acumular. Generosidade não dispensa honestidade no modo de ganhar.", "Cumpra acordos justos, reconheça direitos e escolha como colaborar dentro das suas possibilidades. Não use uma doação para encobrir o prejuízo causado a alguém.", "Lucas 12:13–21 · Tiago 5:1–6"], ["Discussão política enquanto o próximo precisa", "Debater política e buscar mudanças na sociedade podem fazer parte da responsabilidade pelo bem comum. Discordar de alguém não é, por si, pecado.", "O exame começa quando mentira, humilhação, desumanização, ameaça ou corrupção entram na defesa de uma posição. Também vale perguntar se a disputa serve de desculpa para ignorar uma necessidade que podemos atender.", "Confira a informação antes de compartilhar, critique propostas sem negar a dignidade de pessoas e escolha uma ação concreta de cuidado. Conversa pública e solidariedade podem caminhar juntas.", "Efésios 4:25–32 · Tiago 2:14–17"], ["Fazer o bem para parecer melhor", "Uma ação generosa pode ser boa; o reconhecimento recebido não a torna automaticamente falsa. Mas a intenção merece exame quando a imagem pública passa a valer mais que a pessoa atendida.", "Expor a dor de alguém para ganhar aprovação, usar religião como superioridade e rejeitar toda correção podem alimentar soberba. A dignidade de quem recebe ajuda não é material de propaganda.", "Peça autorização quando cabível, preserve a privacidade e sirva também quando ninguém está olhando. Aceite aprender com quem você deseja ajudar.", "Mateus 6:1–4 · Filipenses 2:3–8"], ["Comparação, inveja e desânimo", "Ao ver a conquista de outra pessoa, pode surgir desconforto ou tristeza. Sentir isso não obriga você a desprezar alguém nem prova que sua vida perdeu valor.", "O exame é perceber se você passa a inventar defeitos, espalhar comentários ou desejar o mal para diminuir a conquista do outro.", "Reconheça a emoção, reduza comparações que fazem mal e valorize um passo possível na sua própria caminhada. É possível celebrar o bem do outro e pedir apoio para si.", "Tiago 3:13–18 · Romanos 12:15"], ["Descansar ou abandonar o que posso fazer?", "Você tem uma responsabilidade, mas também pode estar cansado, doente ou sem recursos para realizá-la. Essas situações precisam ser consideradas com honestidade.", "Negligência deliberada não deve ser confundida automaticamente com depressão, TDAH, esgotamento ou limitações de saúde. O exame considera o que está realmente ao alcance, sem cobrar desempenho impossível.", "Escolha um passo pequeno, organize ajuda e respeite o descanso necessário. Quando puder agir, transforme o aprendizado em cuidado concreto.", "Romanos 12:9–13 · Marcos 6:30–32"]]}, "en": {"eyebrow": "UNDERSTAND, DISCERN AND CHANGE", "title": "Understanding sin. Cultivating a life of love.", "intro": "What does the Bible call sin? How can we recognize attitudes that harm our relationship with God and our neighbour? Here, study connects with examples and paths of repentance, care and making amends.", "summaryNote": "These explanations are the platform’s summaries and applications, not literal quotations. Open the references to read passages in context. This is not a complete list of every sin.", "definitionTitle": "What is sin?", "definition": "From a biblical perspective, sin involves transgressing God’s will and practising injustice. It can also involve omitting the good we know we ought to do. Examination includes actions, words, cultivated desires and omissions rather than religious appearances alone.", "definitionRefs": [{"label": "1 John 3:4", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}, {"label": "1 John 5:17", "url": "https://www.bibliaonline.com.br/acf/1jo/5"}, {"label": "James 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "Mark 7:20–23", "url": "https://www.bibliaonline.com.br/acf/mc/7"}], "idolatryTitle": "Idolatry: what takes God’s place?", "idolatry": "Biblical faith rejects giving another what belongs to God. The problem also appears when money, power or interests become absolute and are used to justify harming someone. Colossians associates greed with idolatry; Jesus contrasts serving God and money.", "idolatryExample": "For example, defending your faith does not authorize threats, humiliation or attacks against people who believe differently. You can disagree firmly and still treat others with dignity. Hatred and violence must be examined as actions without condemning an entire group.", "idolatryRefs": [{"label": "Exodus 20:3–6", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Matthew 6:24", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Colossians 3:5", "url": "https://www.bibliaonline.com.br/acf/cl/3"}, {"label": "Matthew 5:43–48", "url": "https://www.bibliaonline.com.br/acf/mt/5"}, {"label": "1 John 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}], "images": "Christian traditions interpret the use of images differently. The Catholic Catechism distinguishes veneration of images from the worship owed to God alone (2132). When comparing practices, identify the tradition and its teaching rather than assuming each person’s intention.", "imagesAction": "Read the Catholic explanation of images", "gravityTitle": "Mortal, venial and capital sins: what is the difference?", "gravity": "In Catholic teaching, mortal sin requires all three: grave matter, full knowledge and deliberate consent. Venial sin involves less serious matter or a lack of full knowledge/consent in grave matter. A list of acts alone cannot judge someone’s responsibility.", "gravityNote": "Other Christian communities do not necessarily use this classification in the same way. It is presented here as Catholic teaching, with its source.", "gravityAction": "Read Catechism 1854–1864", "graveTitle": "Examples of serious conduct to study", "graveIntro": "The references help recognize wrongdoing and seek change. The seriousness of conduct and personal responsibility must not be confused with an automatic judgement of someone’s spiritual situation.", "examples": [["Violence and murder", "Attacking life, threatening and humiliating harm our neighbour. Jesus also challenges anger expressed through insults.", "Stop aggression and seek safety and help. Reconciliation does not require remaining in a violent situation.", [{"label": "Exodus 20:13", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Matthew 5:21–24", "url": "https://www.bibliaonline.com.br/acf/mt/5"}]], ["Theft, lies and fraud", "Taking what belongs to others, deceiving for gain and bearing false witness destroy trust and cause harm.", "Acknowledge the wrongdoing, correct the information and seek to make amends responsibly.", [{"label": "Exodus 20:15–16", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Ephesians 4:25–28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Unfaithfulness and using others", "Adultery, exploitation and relationships that disregard others’ dignity contradict faithfulness and care.", "Set boundaries, leave harmful conduct behind and seek responsible guidance.", [{"label": "Exodus 20:14", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "1 Thessalonians 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Greed and exploitation", "Placing profit above justice can lead to exploitation, withholding what is owed and treating people as means to wealth.", "Practise fair agreements and honesty. Share according to your abilities and responsibilities.", [{"label": "Luke 12:13–21", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "James 5:1–6", "url": "https://www.bibliaonline.com.br/acf/tg/5"}]], ["Hatred and hurtful words", "Slander, contempt and words used to destroy do not fit love of neighbour.", "Pause, avoid sending an insult and try to express the disagreement truthfully and respectfully.", [{"label": "Ephesians 4:29–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "1 John 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}]], ["Omission in the face of need", "Knowing we can do good and deliberately ignoring it also calls for examination. Care must consider what is actually within our reach.", "Choose one possible act of help without exposing or pressuring the person receiving it.", [{"label": "James 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "1 John 3:17–18", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}]]], "causesTitle": "What can lead us into wrongdoing?", "causesIntro": "James describes a progression from cultivated desire to sin. In practice, it is worth noticing choices, habits and excuses. Environments influence opportunities, but a quiet place does not guarantee freedom from anger and religious appearances do not guarantee integrity.", "causes": ["Wanting an advantage and justifying the harm it causes.", "Repeating conduct until we stop considering its consequences.", "Giving in to group pressure or the need to appear superior.", "Holding resentment and choosing to nourish revenge.", "Ignoring correction and seeking only people who confirm our choices.", "Confusing a temptation or involuntary thought with a deliberate decision: feeling or thinking something is not automatically choosing to act on it."], "causesRefs": [{"label": "James 1:13–15", "url": "https://www.bibliaonline.com.br/acf/tg/1"}, {"label": "Romans 12:2", "url": "https://www.bibliaonline.com.br/acf/rm/12"}, {"label": "Proverbs 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}], "capitalTitle": "The seven capital sins in everyday life", "capitalNote": "Capital sins are vices that foster other sins; they do not automatically equal mortal sins.", "capitalIntro": "We connect the teaching with concrete actions: recognize harm, cultivate a virtue and prepare conditions for acting better. These examples are applications, not diagnoses of people.", "capital": [["Pride", "Humility", "Seeking superiority and despising others can prevent listening and accepting correction.", "Listen carefully to an opinion, acknowledge a mistake and thank someone for help.", [{"label": "Philippians 2:3–8", "url": "https://www.bibliaonline.com.br/acf/fp/2"}]], ["Avarice and greed", "Generosity and justice", "Placing accumulation above everything can crowd out sharing and honesty.", "Pay what is owed, refuse unfair advantages and set aside help within your means.", [{"label": "Luke 12:15", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "Ephesians 4:28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Envy", "Gratitude and goodwill", "Nurtured comparison can turn into resentment and a desire to diminish others’ good.", "Recognize someone’s qualities without turning the conversation into competition.", [{"label": "James 3:13–18", "url": "https://www.bibliaonline.com.br/acf/tg/3"}]], ["Destructive anger", "Gentleness and self-control", "Anger can become insult, threat or aggression when we choose to feed it and hurt others.", "Reduce confrontational stimuli, pause and return to the conversation safely and respectfully.", [{"label": "Ephesians 4:26–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "Proverbs 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}]], ["Lust", "Respect and faithfulness", "Reducing someone to an object and betraying commitments harms relationships and dignity.", "Set limits around harmful conduct and choose respectful relationships without exploitation.", [{"label": "1 Thessalonians 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Gluttony", "Temperance and care", "Studying temperance invites examination of excess, waste and failure to share. Someone’s body does not reveal their moral life.", "Care for your diet according to your needs and access, avoid waste and share when possible.", [{"label": "1 Corinthians 10:23–31", "url": "https://www.bibliaonline.com.br/acf/1co/10"}, {"label": "Isaiah 58:7", "url": "https://www.bibliaonline.com.br/acf/is/58"}]], ["Sloth or spiritual neglect", "Achievable diligence", "Deliberately abandoning responsibility must be distinguished from needing rest or facing real limitations.", "Choose an achievable task and ask for support. Fatigue, ADHD, depression and illness do not automatically mean moral neglect.", [{"label": "Romans 12:9–13", "url": "https://www.bibliaonline.com.br/acf/rm/12"}]]], "fastingTitle": "Fasting, gluttony and food: how can we connect them with care?", "fasting": "In Matthew 6:16–18, Jesus teaches fasting without religious display. Isaiah 58 connects fasting with justice, liberation from oppression and sharing bread. The platform invites reflection on humility, self-control and generosity through these passages.", "fastingHealth": "Religious fasting does not guarantee weight loss, diabetes prevention or freedom from illness. Weight and diagnoses do not measure holiness or show that someone practises gluttony. People with diabetes should consult their health team before fasting; do not change food intake or medication on your own to meet a website challenge.", "fastingPractice": "One possible step: examine waste, care for a meal within your circumstances and share something within your means. If you wish to fast, discuss the practice with your community and respect health guidance. No duration, competition or weight target is proposed here.", "fastingRefs": [{"label": "Matthew 6:16–18", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Isaiah 58:6–10", "url": "https://www.bibliaonline.com.br/acf/is/58"}], "fastingHealthAction": "Diabetes and fasting · IDF guidance", "changeTitle": "Recognize, repent and make amends", "changeIntro": "The purpose is to seek truth, forgiveness and change rather than remain trapped in accusation. Zacchaeus’ story connects meeting Jesus with making amends; James calls us to put the Word into practice.", "changeSteps": ["Recognize a concrete attitude without reducing your entire identity to it.", "Turn to God in prayer and seek guidance in your faith community.", "Stop the harm and respect the safety of those affected.", "Make amends responsibly where possible; asking forgiveness does not oblige another person to resume a relationship.", "Prepare a habit and environment that support change. Seek qualified help if needed."], "changeRefs": [{"label": "Luke 19:1–10", "url": "https://www.bibliaonline.com.br/acf/lc/19"}, {"label": "1 John 1:8–9", "url": "https://www.bibliaonline.com.br/acf/1jo/1"}, {"label": "James 1:22", "url": "https://www.bibliaonline.com.br/acf/tg/1"}], "careNote": "This study must not be used to humiliate, diagnose or persecute people. If the subject causes intense distress, you can take a break and seek human support.", "practiceLabel": "One possible step", "virtueLabel": "Cultivate", "read": "Read the passage · ACF in Portuguese ↗", "sourceLabel": "Doctrinal sources and limits", "sourceText": "An introductory Christian summary. Mortal/venial classification and Catholic teaching on images identify their tradition. Specific pastoral questions call for accompaniment without automatic verdicts about people.", "seekingLink": "Understanding sin →", "careLink": "Fasting and food: understanding with care →", "helpLink": "Welcome and support →", "studyLink": "Continue to Seeking →", "everydayTitle": "From church to life: recognizing wrongdoing in daily situations", "everydayIntro": "Knowing a name is not enough: study gains meaning when we notice the attitude, the harm and a possible way forward. These situations are illustrative, not real accounts or a tool for judging other people’s consciences.", "sceneLabel": "The situation", "discernLabel": "What to examine", "actionLabel": "A path to change", "reasonTitle": "Reasoning to bring into life", "reasonText": "Religious practice can teach us, but attending worship alone does not guarantee consistency outside it. We can ask: what am I seeking? Which means am I using? Who is affected? Am I respecting truth and dignity? What just and loving action can I choose now? There is no need to monitor every thought without rest; the purpose is to recognize concrete choices and learn to act.", "planLink": "Proposed talks, articles and books →", "everyday": [["When looking turns into coveting", "You notice an attractive person or something you would like to own. Noticing is not the same as deciding to exploit someone, betray a commitment or take what belongs to another.", "Examine what you choose to nurture: objectifying someone, justifying betrayal or developing deception to obtain what you want. Temptation does not make theft or violence inevitable.", "Acknowledge desire without treating it as an order. Respect people and commitments; stop conduct that causes harm. If the pursuit has become a harmful habit, ask for support to change.", "Matthew 5:27–30 · James 1:13–15"], ["Food, waste and sharing", "Food is available, and someone is in need. The examination is not about measuring the eater’s body but asking how resources are used and whether we can share responsibly.", "Waste for show or deliberately refusing possible help can reveal indifference. Food needs vary; eating what is needed or treating illness is not a moral failure.", "Arrange a meal within your circumstances, care for what can be used and offer possible help without policing someone’s plate or humiliating their body.", "Isaiah 58:7 · 1 John 3:17–18"], ["Anger in conversation or online", "A disagreement brings anger. You can acknowledge the feeling without sending a threat, exposing someone or turning conflict into aggression.", "Notice when the intention shifts from clarifying a problem to causing hurt. A less provocative environment may help, but choosing boundaries and ways to respond also matters.", "Pause before posting, check what you understood and revisit the issue respectfully when it is safe. If harm was caused, acknowledge it and seek to make amends.", "Ephesians 4:26–32 · Proverbs 15:1"], ["Earning more and forgetting those nearby", "Wanting a better life or saving for real needs does not automatically equal greed. The problem appears when profit matters more than justice and dignity.", "Examine fraud, withholding what is owed, exploitation and the idea that any means is acceptable for accumulation. Generosity does not replace honesty in earning.", "Honour fair agreements, recognize rights and choose how to help within your means. Do not use a donation to conceal harm caused to someone.", "Luke 12:13–21 · James 5:1–6"], ["Political arguments while a neighbour needs help", "Debating politics and seeking social change can be part of responsibility for the common good. Disagreeing is not in itself a sin.", "Examination begins when lies, humiliation, dehumanization, threats or corruption enter the defence of a position. Also ask whether the dispute excuses ignoring a need we can meet.", "Check information before sharing it, criticize proposals without denying people’s dignity and choose a concrete act of care. Public discussion and solidarity can go together.", "Ephesians 4:25–32 · James 2:14–17"], ["Doing good to appear superior", "A generous action can be good; recognition does not automatically make it false. But motives deserve examination when public image matters more than the person being helped.", "Exposing someone’s pain for approval, using religion to claim superiority and rejecting all correction can foster pride. A recipient’s dignity is not publicity material.", "Ask permission where appropriate, protect privacy and serve when no one is watching too. Be willing to learn from those you want to help.", "Matthew 6:1–4 · Philippians 2:3–8"], ["Comparison, envy and discouragement", "Seeing someone else’s achievement may bring discomfort or sadness. That feeling does not force you to despise them or prove your own life has lost value.", "Notice whether you begin inventing faults, spreading comments or wishing harm to diminish the other person’s achievement.", "Acknowledge the emotion, reduce harmful comparisons and value an achievable step on your own journey. You can celebrate another person’s good and ask for support yourself.", "James 3:13–18 · Romans 12:15"], ["Resting or abandoning what I can do?", "You have a responsibility, but you may also be tired, ill or without the resources to fulfil it. These circumstances deserve honest consideration.", "Deliberate neglect should not automatically be confused with depression, ADHD, exhaustion or health limitations. Examine what is actually achievable without demanding impossible performance.", "Choose a small step, arrange help and respect necessary rest. When you can act, turn learning into practical care.", "Romans 12:9–13 · Mark 6:30–32"]]}, "es": {"eyebrow": "ENTENDER, DISCERNIR Y CAMBIAR", "title": "Entender el pecado. Cultivar una vida de amor.", "intro": "¿Qué llama pecado la Biblia? ¿Cómo reconocer actitudes que dañan nuestra relación con Dios y el prójimo? Aquí el estudio se relaciona con ejemplos y caminos de arrepentimiento, cuidado y reparación.", "summaryNote": "Las explicaciones son síntesis y aplicaciones de la plataforma, no citas literales. Abre las referencias para leer el pasaje en su contexto. No es una lista completa de todos los pecados.", "definitionTitle": "¿Qué es el pecado?", "definition": "Desde la perspectiva bíblica, el pecado implica transgredir la voluntad de Dios y practicar la injusticia. También puede implicar omitir el bien que sabemos que debemos hacer. El examen incluye acciones, palabras, deseos cultivados y omisiones, no solo la apariencia religiosa.", "definitionRefs": [{"label": "1 Juan 3:4", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}, {"label": "1 Juan 5:17", "url": "https://www.bibliaonline.com.br/acf/1jo/5"}, {"label": "Santiago 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "Marcos 7:20–23", "url": "https://www.bibliaonline.com.br/acf/mc/7"}], "idolatryTitle": "Idolatría: ¿qué ocupa el lugar de Dios?", "idolatry": "La fe bíblica rechaza dar a otro el lugar que pertenece a Dios. El problema también aparece cuando el dinero, el poder o los intereses se vuelven absolutos y justifican perjudicar a alguien. Colosenses asocia la avaricia con la idolatría; Jesús contrapone servir a Dios y al dinero.", "idolatryExample": "Por ejemplo, defender la propia fe no autoriza amenazar, humillar o agredir a quien cree de otra forma. Se puede discrepar con firmeza y seguir tratando al otro con dignidad. El odio y la violencia deben examinarse como actitudes, sin condenar a un grupo entero.", "idolatryRefs": [{"label": "Éxodo 20:3–6", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Mateo 6:24", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Colosenses 3:5", "url": "https://www.bibliaonline.com.br/acf/cl/3"}, {"label": "Mateo 5:43–48", "url": "https://www.bibliaonline.com.br/acf/mt/5"}, {"label": "1 Juan 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}], "images": "Las tradiciones cristianas interpretan de forma distinta el uso de imágenes. El Catecismo católico distingue la veneración de imágenes de la adoración debida solo a Dios (2132). Al comparar prácticas, identifica la tradición y su enseñanza en vez de suponer la intención de cada persona.", "imagesAction": "Consultar la explicación católica sobre imágenes", "gravityTitle": "Pecado mortal, venial y capital: ¿cuál es la diferencia?", "gravity": "En la doctrina católica, el pecado mortal exige, juntos: materia grave, pleno conocimiento y consentimiento deliberado. El venial implica materia leve o ausencia de pleno conocimiento/consentimiento en materia grave. Una lista de actos no basta para juzgar la responsabilidad personal.", "gravityNote": "Otras comunidades cristianas no usan necesariamente esta clasificación del mismo modo. Aquí se presenta como doctrina católica, con su fuente de consulta.", "gravityAction": "Leer Catecismo 1854–1864", "graveTitle": "Ejemplos de conductas graves para estudiar", "graveIntro": "Las referencias ayudan a reconocer el mal y buscar el cambio. La gravedad de una conducta y la responsabilidad personal no deben confundirse con un juicio automático sobre la situación espiritual de alguien.", "examples": [["Violencia y homicidio", "Atentar contra la vida, amenazar y humillar dañan al prójimo. Jesús también confronta la ira que se expresa en ofensas.", "Detén la agresión y busca seguridad y ayuda. La reconciliación no exige permanecer en una situación violenta.", [{"label": "Éxodo 20:13", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Mateo 5:21–24", "url": "https://www.bibliaonline.com.br/acf/mt/5"}]], ["Robo, mentira y fraude", "Tomar lo ajeno, engañar para obtener ventajas y dar falso testimonio destruyen la confianza y causan daño.", "Reconoce el error, corrige la información y busca reparar el daño de manera responsable.", [{"label": "Éxodo 20:15–16", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "Efesios 4:25–28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Infidelidad y uso de otras personas", "El adulterio, la explotación y las relaciones que ignoran la dignidad del otro contradicen la fidelidad y el cuidado.", "Establece límites, abandona la conducta perjudicial y busca orientación responsable.", [{"label": "Éxodo 20:14", "url": "https://www.bibliaonline.com.br/acf/ex/20"}, {"label": "1 Tesalonicenses 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Codicia y explotación", "Poner la ganancia por encima de la justicia puede llevar a explotar, retener lo debido y tratar a las personas como medios para enriquecerse.", "Practica acuerdos justos y honestidad. Comparte según tus posibilidades y responsabilidades.", [{"label": "Lucas 12:13–21", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "Santiago 5:1–6", "url": "https://www.bibliaonline.com.br/acf/tg/5"}]], ["Odio y palabras que hieren", "La calumnia, el desprecio y las palabras usadas para destruir no concuerdan con el amor al prójimo.", "Haz una pausa, evita enviar la ofensa y procura expresar el conflicto con verdad y respeto.", [{"label": "Efesios 4:29–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "1 Juan 4:20–21", "url": "https://www.bibliaonline.com.br/acf/1jo/4"}]], ["Omisión ante la necesidad", "Saber que podemos hacer el bien e ignorarlo deliberadamente también requiere examen. El cuidado debe considerar lo que realmente está a nuestro alcance.", "Elige una ayuda concreta posible, sin exponer ni presionar a quien la recibe.", [{"label": "Santiago 4:17", "url": "https://www.bibliaonline.com.br/acf/tg/4"}, {"label": "1 Juan 3:17–18", "url": "https://www.bibliaonline.com.br/acf/1jo/3"}]]], "causesTitle": "¿Qué puede conducirnos al error?", "causesIntro": "Santiago describe un recorrido del deseo cultivado al pecado. En la práctica, conviene observar decisiones, hábitos y justificaciones. El entorno influye en las oportunidades, pero un lugar tranquilo no garantiza la ausencia de ira y una apariencia religiosa no garantiza integridad.", "causes": ["Desear una ventaja y justificar el daño que causa.", "Repetir una conducta hasta dejar de examinar sus consecuencias.", "Ceder a la presión de un grupo o a la necesidad de parecer superior.", "Guardar resentimiento y elegir alimentar la venganza.", "Ignorar una corrección y buscar solo a quienes confirman nuestras decisiones.", "Confundir una tentación o un pensamiento involuntario con una decisión deliberada: sentir o pensar algo no es automáticamente elegir practicarlo."], "causesRefs": [{"label": "Santiago 1:13–15", "url": "https://www.bibliaonline.com.br/acf/tg/1"}, {"label": "Romanos 12:2", "url": "https://www.bibliaonline.com.br/acf/rm/12"}, {"label": "Proverbios 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}], "capitalTitle": "Los siete pecados capitales en la vida cotidiana", "capitalNote": "Los capitales son vicios que favorecen otros pecados; no equivalen automáticamente a pecados mortales.", "capitalIntro": "Relacionamos la enseñanza con acciones concretas: reconocer el daño, cultivar una virtud y preparar condiciones para actuar mejor. Son aplicaciones, no diagnósticos de personas.", "capital": [["Soberbia", "Humildad", "Buscar la superioridad y despreciar al otro puede impedir escuchar y aceptar correcciones.", "Escucha una opinión con atención, reconoce un error y agradece una ayuda.", [{"label": "Filipenses 2:3–8", "url": "https://www.bibliaonline.com.br/acf/fp/2"}]], ["Avaricia y codicia", "Generosidad y justicia", "Poner la acumulación por encima de todo puede cerrar el espacio para compartir y actuar con honestidad.", "Cumple lo debido, rechaza ventajas injustas y reserva una ayuda compatible con tus recursos.", [{"label": "Lucas 12:15", "url": "https://www.bibliaonline.com.br/acf/lc/12"}, {"label": "Efesios 4:28", "url": "https://www.bibliaonline.com.br/acf/ef/4"}]], ["Envidia", "Gratitud y benevolencia", "La comparación alimentada puede convertirse en resentimiento y deseo de menospreciar el bien del otro.", "Reconoce una cualidad de alguien sin transformar la conversación en una competición.", [{"label": "Santiago 3:13–18", "url": "https://www.bibliaonline.com.br/acf/tg/3"}]], ["Ira destructiva", "Mansedumbre y dominio propio", "La ira puede convertirse en insulto, amenaza o agresión cuando elegimos alimentarla y herir.", "Reduce los estímulos de confrontación, haz una pausa y retoma la conversación con seguridad y respeto.", [{"label": "Efesios 4:26–32", "url": "https://www.bibliaonline.com.br/acf/ef/4"}, {"label": "Proverbios 15:1", "url": "https://www.bibliaonline.com.br/acf/pv/15"}]], ["Lujuria", "Respeto y fidelidad", "Reducir a alguien a un objeto y traicionar compromisos daña las relaciones y la dignidad.", "Prepara límites para las conductas perjudiciales y elige relaciones respetuosas, sin explotación.", [{"label": "1 Tesalonicenses 4:3–8", "url": "https://www.bibliaonline.com.br/acf/1ts/4"}]], ["Gula", "Templanza y cuidado", "Estudiar la templanza invita a examinar los excesos, el desperdicio y la falta de compartir. El cuerpo de alguien no revela su vida moral.", "Cuida la alimentación según tus necesidades y acceso, evita el desperdicio y comparte cuando sea posible.", [{"label": "1 Corintios 10:23–31", "url": "https://www.bibliaonline.com.br/acf/1co/10"}, {"label": "Isaías 58:7", "url": "https://www.bibliaonline.com.br/acf/is/58"}]], ["Pereza o negligencia espiritual", "Diligencia posible", "Hay que distinguir abandonar deliberadamente una responsabilidad de necesitar descanso o afrontar limitaciones reales.", "Elige una tarea posible y pide apoyo. El cansancio, el TDAH, la depresión y la enfermedad no son automáticamente negligencia moral.", [{"label": "Romanos 12:9–13", "url": "https://www.bibliaonline.com.br/acf/rm/12"}]]], "fastingTitle": "Ayuno, gula y alimentación: ¿cómo relacionarlos con el cuidado?", "fasting": "En Mateo 6:16–18, Jesús enseña a ayunar sin exhibición religiosa. Isaías 58 relaciona el ayuno con la justicia, la liberación de la opresión y compartir el pan. La plataforma propone reflexionar sobre humildad, dominio propio y generosidad a partir de estos pasajes.", "fastingHealth": "El ayuno religioso no garantiza adelgazar, prevenir la diabetes ni evitar enfermedades. El peso y los diagnósticos no miden la santidad ni permiten concluir que alguien practica la gula. Las personas con diabetes deben consultar al equipo de salud antes de ayunar; no cambies por tu cuenta la alimentación o la medicación para cumplir un desafío del sitio.", "fastingPractice": "Un paso posible: examina el desperdicio, cuida una comida según tu realidad y comparte algo que esté a tu alcance. Si deseas ayunar, conversa sobre la práctica con tu comunidad y respeta la orientación de salud. Aquí no se propone ninguna duración, competición o meta de peso.", "fastingRefs": [{"label": "Mateo 6:16–18", "url": "https://www.bibliaonline.com.br/acf/mt/6"}, {"label": "Isaías 58:6–10", "url": "https://www.bibliaonline.com.br/acf/is/58"}], "fastingHealthAction": "Diabetes y ayuno · orientación de la IDF", "changeTitle": "Reconocer, arrepentirse y reparar", "changeIntro": "El objetivo es buscar verdad, perdón y cambio, no quedar atrapado en la acusación. La historia de Zaqueo relaciona el encuentro con Jesús con la reparación; Santiago llama a poner la Palabra en práctica.", "changeSteps": ["Reconoce una actitud concreta sin reducir toda tu identidad a ella.", "Vuélvete a Dios en oración y busca orientación en tu comunidad de fe.", "Interrumpe el daño y respeta la seguridad de quienes fueron afectados.", "Repara lo posible con responsabilidad; pedir perdón no obliga a otra persona a retomar una relación.", "Prepara un hábito y un entorno que apoyen el cambio. Busca ayuda cualificada si la necesitas."], "changeRefs": [{"label": "Lucas 19:1–10", "url": "https://www.bibliaonline.com.br/acf/lc/19"}, {"label": "1 Juan 1:8–9", "url": "https://www.bibliaonline.com.br/acf/1jo/1"}, {"label": "Santiago 1:22", "url": "https://www.bibliaonline.com.br/acf/tg/1"}], "careNote": "Este estudio no debe usarse para humillar, diagnosticar o perseguir a las personas. Si el tema provoca angustia intensa, puedes hacer una pausa y buscar apoyo humano.", "practiceLabel": "Un paso posible", "virtueLabel": "Cultivar", "read": "Leer el pasaje · ACF en portugués ↗", "sourceLabel": "Fuentes doctrinales y límites", "sourceText": "Síntesis cristiana introductoria. La clasificación mortal/venial y la explicación católica sobre imágenes identifican su tradición. Las preguntas pastorales específicas requieren acompañamiento, sin veredictos automáticos sobre las personas.", "seekingLink": "Entender el pecado →", "careLink": "Ayuno y alimentación: entender con cuidado →", "helpLink": "Acogida y apoyo →", "studyLink": "Continuar en Buscando →", "everydayTitle": "De la iglesia a la vida: reconocer el error cotidiano", "everydayIntro": "Conocer un nombre no basta: el estudio cobra sentido cuando percibimos la actitud, el daño y una salida posible. Son situaciones ilustrativas, no relatos reales ni una herramienta para juzgar la conciencia ajena.", "sceneLabel": "La situación", "discernLabel": "Qué examinar", "actionLabel": "Un camino de cambio", "reasonTitle": "Un razonamiento para llevar a la vida", "reasonText": "La práctica religiosa puede enseñarnos, pero asistir al culto no garantiza por sí solo la coherencia fuera de él. Podemos preguntar: ¿qué busco?, ¿qué medios uso?, ¿a quién afecta?, ¿respeto la verdad y la dignidad?, ¿qué actitud justa y amorosa puedo elegir ahora? No hace falta vigilar cada pensamiento sin descanso; el propósito es reconocer decisiones concretas y aprender a actuar.", "planLink": "Temas propuestos para charlas, artículos y libros →", "everyday": [["Cuando mirar se convierte en codiciar", "Notas a una persona atractiva o un bien que te gustaría tener. Percibirlo no es lo mismo que decidir explotar a alguien, traicionar un compromiso o tomar lo ajeno.", "Examina lo que eliges alimentar: convertir a alguien en objeto, justificar una traición o cultivar un engaño para conseguir lo deseado. La tentación no hace inevitable el robo o la violencia.", "Reconoce el deseo sin tratarlo como una orden. Respeta a la persona y tus compromisos; interrumpe la conducta que daña. Si la búsqueda se convirtió en un hábito perjudicial, pide apoyo para cambiar.", "Mateo 5:27–30 · Santiago 1:13–15"], ["El plato, el desperdicio y compartir", "Hay alimentos disponibles y también alguien que necesita ayuda. El examen no consiste en medir el cuerpo de quien come, sino en preguntar cómo usamos los recursos y si podemos compartir con responsabilidad.", "Desperdiciar para ostentar o rechazar deliberadamente una ayuda posible puede revelar indiferencia. Las necesidades alimentarias varían; comer lo necesario o tratar una enfermedad no es una falta moral.", "Organiza una comida según tus condiciones, cuida lo que puede aprovecharse y ofrece una ayuda posible, sin vigilar el plato ni humillar el cuerpo de nadie.", "Isaías 58:7 · 1 Juan 3:17–18"], ["Ira en una conversación o en las redes", "Un desacuerdo despierta ira. Puedes reconocer la emoción sin enviar una amenaza, exponer a alguien ni convertir el conflicto en agresión.", "Observa cuándo la intención deja de aclarar un problema y pasa a herir. Un entorno menos provocador puede ayudar, pero también importan los límites y las formas de responder.", "Detente antes de publicar, comprueba lo que entendiste y retoma el asunto con respeto cuando sea seguro. Si causaste daño, reconócelo y busca repararlo.", "Efesios 4:26–32 · Proverbios 15:1"], ["Ganar más y olvidar a quienes están al lado", "Desear mejorar de vida o ahorrar para necesidades reales no equivale automáticamente a codicia. El problema aparece cuando la ganancia vale más que la justicia y la dignidad.", "Examina el fraude, retener lo debido, explotar y creer que cualquier medio es aceptable para acumular. La generosidad no sustituye la honestidad al ganar.", "Cumple acuerdos justos, reconoce derechos y elige cómo colaborar según tus posibilidades. No uses una donación para encubrir el daño causado.", "Lucas 12:13–21 · Santiago 5:1–6"], ["Discusión política mientras el prójimo necesita ayuda", "Debatir política y buscar cambios sociales puede formar parte de la responsabilidad por el bien común. Discrepar no es, por sí mismo, pecado.", "El examen empieza cuando la mentira, humillación, deshumanización, amenaza o corrupción entran en la defensa de una postura. Pregunta también si la disputa sirve de excusa para ignorar una necesidad que podemos atender.", "Comprueba la información antes de compartirla, critica propuestas sin negar la dignidad de las personas y elige una acción concreta de cuidado. El debate público y la solidaridad pueden ir juntos.", "Efesios 4:25–32 · Santiago 2:14–17"], ["Hacer el bien para parecer superior", "Una acción generosa puede ser buena; recibir reconocimiento no la vuelve automáticamente falsa. Pero conviene examinar la intención cuando la imagen pública vale más que la persona atendida.", "Exponer el dolor ajeno para ganar aprobación, usar la religión como superioridad y rechazar toda corrección pueden alimentar la soberbia. La dignidad de quien recibe ayuda no es material publicitario.", "Pide permiso cuando corresponda, protege la privacidad y sirve también cuando nadie mira. Acepta aprender de quienes deseas ayudar.", "Mateo 6:1–4 · Filipenses 2:3–8"], ["Comparación, envidia y desánimo", "Al ver un logro ajeno puede surgir malestar o tristeza. Sentirlo no obliga a despreciar a alguien ni demuestra que tu vida haya perdido valor.", "Observa si empiezas a inventar defectos, difundir comentarios o desear el mal para disminuir el logro del otro.", "Reconoce la emoción, reduce las comparaciones perjudiciales y valora un paso posible en tu propio camino. Puedes celebrar el bien ajeno y pedir apoyo para ti.", "Santiago 3:13–18 · Romanos 12:15"], ["¿Descansar o abandonar lo que puedo hacer?", "Tienes una responsabilidad, pero también puedes estar cansado, enfermo o sin recursos para cumplirla. Esas circunstancias deben considerarse con honestidad.", "La negligencia deliberada no debe confundirse automáticamente con depresión, TDAH, agotamiento o limitaciones de salud. Examina lo que realmente está al alcance, sin exigir un rendimiento imposible.", "Elige un paso pequeño, organiza ayuda y respeta el descanso necesario. Cuando puedas actuar, transforma el aprendizaje en cuidado concreto.", "Romanos 12:9–13 · Marcos 6:30–32"]]}},lang=window.platformLocale||'pt';let data=all[lang]||all.pt;
const id=x=>document.getElementById(x);function link(url,text){try{const u=new URL(url);if(u.protocol!=='https:')return null;const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=text;return a;}catch(e){return null;}}
function refs(rows,box){box.replaceChildren();box.classList.add('sin-refs');for(const row of rows||[]){if(!row||typeof row.label!=='string')continue;const a=link(row.url,row.label+' · '+data.read);if(a)box.append(a);}}
function list(items,target){const ul=id(target);ul.replaceChildren();for(const text of items){if(typeof text!=='string')continue;const li=document.createElement('li');li.textContent=text;ul.append(li);}}
function cards(rows,target,capital){const box=id(target);box.replaceChildren();for(const row of rows){if(!Array.isArray(row)||row.length!==(capital?5:4))continue;const details=document.createElement('details');details.className='sin-card';const summary=document.createElement('summary');summary.textContent=row[0];details.append(summary);if(capital){const virtue=document.createElement('p');virtue.className='sin-virtue';virtue.textContent=data.virtueLabel+': '+row[1];details.append(virtue);}const p=document.createElement('p');p.textContent=row[capital?2:1];const h=document.createElement('h4');h.textContent=data.practiceLabel;const practice=document.createElement('p');practice.textContent=row[capital?3:2];const references=document.createElement('div');refs(row[row.length-1],references);details.append(p,h,practice,references);box.append(details);}}
function render(d){if(!d||typeof d.title!=='string'||!Array.isArray(d.capital)||d.capital.length!==7||!Array.isArray(d.examples))return;data=d;for(const el of document.querySelectorAll('[data-sin]'))if(typeof d[el.dataset.sin]==='string')el.textContent=d[el.dataset.sin];for(const el of document.querySelectorAll('[data-sin-refs]'))refs(d[el.dataset.sinRefs],el);list(d.causes,'sin-causes');list(d.changeSteps,'sin-change');cards(d.examples,'sin-examples',false);const caseBox=id('sin-everyday');caseBox.replaceChildren();for(const row of d.everyday||[]){const article=document.createElement('details');article.className='sin-card';const summary=document.createElement('summary');summary.textContent=row[0];article.append(summary);for(const [index,key] of [[1,'sceneLabel'],[2,'discernLabel'],[3,'actionLabel']]){const h=document.createElement('h4');h.textContent=d[key];const p=document.createElement('p');p.textContent=row[index];article.append(h,p);}const references=document.createElement('p');references.className='small-note';references.textContent=row[4];article.append(references);caseBox.append(article);}cards(d.capital,'sin-capital',true);id('sin-from-seeking').textContent=d.seekingLink;id('sin-from-selfcare').textContent=d.careLink;id('sin-selfcare-link').textContent=({pt:'Cuidar de si →',en:'Caring for yourself →',es:'Cuidar de ti →'})[lang];id('sin-gravity-source').href=lang==='es'?'https://www.vatican.va/content/dam/wss/archive/catechism_sp/p3s1c1a8_sp.html':lang==='en'?'https://www.vatican.va/content/catechism/en/part_three/section_one/chapter_one/article_8/iv_the_gravity_of_sin_mortal_and_venial_sin.html':'https://www.vatican.va/archive/cathechism_po/index_new/p3s1cap1_1699-1876_po.html';id('sin-images-source').href=lang==='pt'?'https://www.vatican.va/archive/cathechism_po/index_new/p3s2cap1_2083-2195_po.html':'https://www.vatican.va/content/catechism/en/part_three/section_two/chapter_one/article_1/iv_you_shall_not_make_for_yourself_a_graven_image.index.html';id('sin-health-source').href=lang==='es'?'https://idf.org/es/managing-diabetes/fasting/':'https://idf.org/managing-diabetes/fasting/';}
render(data);window.addEventListener('pge-live-changed',()=>load());async function load(){try{const response=await fetch('dados/pecado.json',{cache:'no-store'});if(response.ok)render(await response.json());}catch(e){}}if(['http:','https:'].includes(location.protocol))load();let last=Date.now();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-last>=300000){last=Date.now();load();}});})();